    found: list[tuple[int, int, time | None]] = []
    occupied: list[tuple[int, int]] = []

    def claim(match: re.Match[str], parsed: time | None) -> None:
        span = match.span()
        if any(span[0] < end and start < span[1] for start, end in occupied):
            return
        occupied.append(span)
        found.append((span[0], span[1], parsed))

    clock_12 = re.compile(r"\b(\d{1,2})(?::(\d{2}))?\s*(am|pm)\b", re.IGNORECASE)
    for match in clock_12.finditer(text):
        parsed = _twelve_hour(int(match.group(1)), int(match.group(2) or 0), match.group(3))
        if parsed is not None:
            claim(match, parsed)
    evening = re.compile(r"\b(\d{1,2})(?::(\d{2}))?\s+in the evening\b", re.IGNORECASE)
    for match in evening.finditer(text):
        hour = int(match.group(1))
        minute = int(match.group(2) or 0)
        if 1 <= hour <= 11 and minute < 60:
            claim(match, time(hour + 12, minute))
    clock_24 = re.compile(r"\b([01]?\d|2[0-3]):([0-5]\d)\b")
    for match in clock_24.finditer(text):
        claim(match, time(int(match.group(1)), int(match.group(2))))
    bare = re.compile(r"\b(?:at|from)\s+(\d{1,2})(?::(\d{2}))?\b", re.IGNORECASE)
    for match in bare.finditer(text):
        claim(match, None)
    explicit = [item[2] for item in found if item[2] is not None]
    bare_count = sum(1 for item in found if item[2] is None)
    unique = list(dict.fromkeys(explicit))
    if bare_count and not unique:
        return None, Ambiguity(
            field=BriefField.time,
            message="Do you mean morning or evening?",
            candidates=["07:00", "19:00"] if bare_count else [],
            blocking=True,
        )
    if bare_count or len(unique) > 1:
        labels = [item.strftime("%H:%M") for item in unique]
        if bare_count:
            labels.extend(["07:00", "19:00"])
        return None, Ambiguity(
            field=BriefField.time,
            message="What time should the evening start?",
            candidates=list(dict.fromkeys(labels))[:6],
            blocking=True,
        )
    if len(unique) == 1:
        return unique[0], None
    return None, None

