import { describe, expect, it } from "vitest";
import type { PlanningBrief } from "../../lib/api/plan";
import {
  activeFollowUp,
  applyLocalTime,
  budgetIssue,
  canFindPlan,
  moveIntent,
  partySizeIssue,
  preferenceIssue,
  restorePrompt,
  shouldResolve,
  visibleWarning,
} from "./flow";

const brief: PlanningBrief = {
  raw_prompt: "Dinner in Kyoto tomorrow at 7",
  destination_text: "Kyoto",
  local_date: null,
  pending_date: { phrase: "tomorrow" },
  local_start: "19:00:00",
  party_size: null,
  budget: null,
  intents: [
    { kind: "dinner", label: "dinner", position: 1 },
    { kind: "walk", label: "walk", position: 2 },
  ],
  preferences: [],
  accessibility_needs: [],
  missing_essentials: [],
  ambiguities: [],
  confidence: "high",
};

describe("planning flow", () => {
  it("keeps the original prompt when a revision replaces it", () => {
    const restored = restorePrompt({ ...brief, raw_prompt: "Kyoto" }, brief.raw_prompt);
    expect(restored.raw_prompt).toBe("Dinner in Kyoto tomorrow at 7");
    expect(restored.destination_text).toBe("Kyoto");
  });

  it("asks one destination question and does not resolve an unnamed place", () => {
    const unnamed = { ...brief, destination_text: null };
    expect(activeFollowUp(unnamed, null, false)?.question).toBe(
      "Which place should this evening be in?",
    );
    expect(shouldResolve(unnamed, null)).toBe(false);
    expect(activeFollowUp(brief, null, true)).toBeNull();
  });

  it("fills a missing local date without replacing an entered date", () => {
    const dated = applyLocalTime(brief, { local_date: "2026-10-05", local_start: "19:00:00" });
    expect(dated.local_date).toBe("2026-10-05");
    expect(dated.pending_date).toBeNull();
    const kept = applyLocalTime(
      { ...brief, local_date: "2026-11-01" },
      { local_date: "2026-10-05", local_start: "18:00:00" },
    );
    expect(kept.local_date).toBe("2026-11-01");
    expect(kept.local_start).toBe("19:00:00");
  });

  it("allows a place search only when the evening is ready and idle", () => {
    const destination = { timezone_name: "Asia/Tokyo" };
    expect(
      canFindPlan({
        destination,
        brief: { ...brief, local_date: "2026-10-05" },
        followUp: null,
        choosing: false,
        busy: false,
      }),
    ).toBe(true);
    expect(
      canFindPlan({
        destination,
        brief,
        followUp: { kind: "missing", field: "date", question: "Which date should this evening be?" },
        choosing: false,
        busy: false,
      }),
    ).toBe(false);
    expect(
      canFindPlan({
        destination: null,
        brief: { ...brief, local_date: "2026-10-05" },
        followUp: null,
        choosing: false,
        busy: false,
      }),
    ).toBe(false);
  });

  it("reorders intents and rejects an incomplete budget or party size", () => {
    const moved = moveIntent(brief.intents, 1, -1);
    expect(moved.map((item) => item.label)).toEqual(["walk", "dinner"]);
    expect(moved.map((item) => item.position)).toEqual([1, 2]);
    expect(partySizeIssue("0")).toMatch(/1 to 20/);
    expect(partySizeIssue("2")).toBeNull();
    expect(budgetIssue("40", "")).toMatch(/together/);
    expect(budgetIssue("40", "USD")).toBeNull();
    expect(preferenceIssue("quiet")).toBeNull();
  });

  it("hides stand-in plan notes", () => {
    expect(visibleWarning("Use captured evidence.")).toBe(false);
    expect(visibleWarning("Live place retrieval has not run.")).toBe(false);
    expect(visibleWarning("No live places matched this evening.")).toBe(true);
  });
});

import { describe, expect, it, vi } from "vitest";
import { interpretBrief, PlanRequestError, requestPlan, resolveDestination } from "./planClient";

const brief = {
  raw_prompt: "Dinner in Kyoto on 2026-10-05 at 7pm",
  destination_text: "Kyoto",
  local_date: "2026-10-05",
  pending_date: null,
  local_start: "19:00:00",
  party_size: null,
  budget: null,
  intents: [{ kind: "dinner", label: "dinner", position: 1 }],
  preferences: [],
  accessibility_needs: [],
  missing_essentials: [],
  ambiguities: [],
  confidence: "high",
};

const destination = {
  label: "Kyoto, Kyoto, Japan",
  source_text: "Kyoto",
  locality: "Kyoto",
  region: "Kyoto",
  country_code: "JP",
  timezone_name: "Asia/Tokyo",
  latitude: 35.01,
  longitude: 135.77,
  serpapi_location: "Kyoto,Kyoto,Japan",
  confidence: "high",
  resolution_source: "locations_api",
  provenance: null,
};

function json(body: unknown, status = 200): Response {
  return new Response(JSON.stringify(body), {
    status,
    headers: { "Content-Type": "application/json" },
  });
}

describe("plan client", () => {
  it("reads a brief and does not treat an ambiguous destination as a transport error", async () => {
    const fetchImpl = vi.fn(async (input: RequestInfo | URL) => {
      const url = String(input);
      if (url.endsWith("/api/v2/briefs/interpret")) {
        return json({
          outcome: "ready_for_retrieval",
          brief,
          destination: null,
          stops: [],
          follow_up: null,
          warnings: ["Live place retrieval has not run."],
        });
      }
      return json(
        {
          status: "ambiguous",
          destination: null,
          choices: [destination, { ...destination, label: "Kyoto, other" }],
          billed_requests: 0,
          local_time: null,
        },
        409,
      );
    });
    const interpreted = await interpretBrief("Dinner in Kyoto on 2026-10-05 at 7pm", { fetchImpl });
    const resolved = await resolveDestination({ query: "Kyoto" }, { fetchImpl });
    expect(interpreted.brief.destination_text).toBe("Kyoto");
    expect(resolved.status).toBe("ambiguous");
    expect(resolved.choices).toHaveLength(2);
  });

  it("keeps quota and timeout failures user-safe", async () => {
    const fetchImpl = vi.fn(async () =>
      json(
        {
          request_id: "req-1",
          contract_version: "2",
          error: {
            code: "QUOTA_EXHAUSTED",
            message: "The search allowance for this plan has been reached.",
            retryable: false,
            next_action: "Try again later.",
            fixture_available: true,
          },
        },
        503,
      ),
    );
    const error = await requestPlan(
      {
        destination,
        intents: brief.intents,
        local_date: "2026-10-05",
        local_start: "19:00:00",
        preferences: [],
        prior_billed_requests: 0,
      },
      { fetchImpl },
    ).catch((caught: unknown) => caught);
    expect(error).toBeInstanceOf(PlanRequestError);
    if (!(error instanceof PlanRequestError)) {
      return;
    }
    expect(error.retryable).toBe(false);
    expect(error.message).not.toMatch(/fixture|prompt|traceback/i);
    expect(error.nextAction).toBe("Try again later.");
  });

  it("reports an unreachable backend without reading a prompt back", async () => {
    const fetchImpl = vi.fn(async () => {
      throw new TypeError("network down");
    });
    const error = await interpretBrief("Dinner in a private place", { fetchImpl }).catch(
      (caught: unknown) => caught,
    );
    expect(error).toBeInstanceOf(PlanRequestError);
    if (!(error instanceof PlanRequestError)) {
      return;
    }
    expect(error.message).toBe("Happen could not be reached.");
    expect(error.message).not.toMatch(/private place/);
  });

  it("lets the caller abort before another search starts", async () => {
    const controller = new AbortController();
    controller.abort();
    await expect(
      resolveDestination({ query: "Kyoto" }, { signal: controller.signal, fetchImpl: vi.fn() }),
    ).rejects.toMatchObject({ name: "AbortError" });
  });
});

